-- Generated by tools/runtime/generate-food-earning-migration.ts.
-- Food earning obligations only; no payout or external transfer acceptance.
SET search_path=bitpos,public;
CREATE TABLE ledger_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_kind text NOT NULL CHECK(owner_kind IN('PLATFORM','MERCHANT','DRIVER','CUSTOMER','PROVIDER')),owner_id uuid NOT NULL,purpose text NOT NULL CHECK(purpose IN('CASH_CLEARING','RECEIVABLE','PAYABLE','REVENUE','REFUND_RESERVE','PAYOUT_RESERVE','PROMOTION_EXPENSE')),currency text NOT NULL CHECK(currency IN('USD','USDG')),decimals smallint NOT NULL CHECK(decimals IN(2,4,6)),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(owner_kind,owner_id,purpose,currency,decimals),UNIQUE(id,currency,decimals));
CREATE TABLE ledger_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),source_kind text NOT NULL,source_id uuid NOT NULL,reason text NOT NULL CHECK(length(reason) BETWEEN 1 AND 1000),currency text NOT NULL CHECK(currency IN('USD','USDG')),decimals smallint NOT NULL CHECK(decimals IN(2,4,6)),reverses_id uuid UNIQUE REFERENCES ledger_transactions,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(source_kind,source_id),UNIQUE(id,currency,decimals));
CREATE TABLE ledger_entries(transaction_id uuid NOT NULL,line smallint NOT NULL CHECK(line BETWEEN 1 AND 200),account_id uuid NOT NULL,currency text NOT NULL,decimals smallint NOT NULL,debit_minor bigint NOT NULL DEFAULT 0,credit_minor bigint NOT NULL DEFAULT 0,PRIMARY KEY(transaction_id,line),FOREIGN KEY(transaction_id,currency,decimals) REFERENCES ledger_transactions(id,currency,decimals),FOREIGN KEY(account_id,currency,decimals) REFERENCES ledger_accounts(id,currency,decimals),CHECK((debit_minor>0 AND credit_minor=0) OR (credit_minor>0 AND debit_minor=0)));
CREATE INDEX ledger_account_history ON ledger_entries(account_id,transaction_id,line);
CREATE FUNCTION draft_assert_ledger_balanced() RETURNS trigger LANGUAGE plpgsql SET search_path=bitpos,pg_temp AS $$
DECLARE target uuid;count_entries integer;balance numeric;
BEGIN
 IF TG_TABLE_NAME='ledger_transactions' THEN target:=NEW.id;ELSE target:=NEW.transaction_id;END IF;
 SELECT count(*),coalesce(sum(debit_minor-credit_minor),0) INTO count_entries,balance FROM ledger_entries WHERE transaction_id=target;
 IF count_entries<2 OR balance<>0 THEN RAISE EXCEPTION 'UNBALANCED_LEDGER' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER ledger_transaction_balanced AFTER INSERT ON ledger_transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION draft_assert_ledger_balanced();
CREATE CONSTRAINT TRIGGER ledger_entries_balanced AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION draft_assert_ledger_balanced();
CREATE TRIGGER ledger_transaction_immutable BEFORE UPDATE OR DELETE ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE TRIGGER ledger_entry_immutable BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE TRIGGER ledger_account_immutable BEFORE UPDATE OR DELETE ON ledger_accounts FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE TABLE order_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),merchant_id uuid NOT NULL,order_id uuid NOT NULL,line_id text NOT NULL,party_kind text NOT NULL CHECK(party_kind IN('MERCHANT','DRIVER','PLATFORM','TAX_AUTHORITY','CUSTOMER')),party_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('ITEM','TAX','DELIVERY','SERVICE','TIP','DISCOUNT','COUPON_FUNDING')),currency text NOT NULL CHECK(currency IN('USD','USDG')),decimals smallint NOT NULL CHECK(decimals IN(2,4,6)),amount_minor bigint NOT NULL,source_quote_id uuid NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),FOREIGN KEY(merchant_id,order_id) REFERENCES orders(merchant_id,id),FOREIGN KEY(merchant_id,source_quote_id) REFERENCES order_quotes(merchant_id,id),UNIQUE(merchant_id,order_id,line_id,party_kind,party_id,kind));
CREATE TRIGGER order_allocation_immutable BEFORE UPDATE OR DELETE ON order_allocations FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE TABLE earning_accruals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),food_assignment_id uuid UNIQUE REFERENCES food_assignments,ride_assignment_id uuid UNIQUE,driver_id uuid NOT NULL REFERENCES driver_occupancy,ledger_transaction_id uuid UNIQUE REFERENCES ledger_transactions,state text NOT NULL CHECK(state IN('ACCRUED','HELD','AVAILABLE','RESERVED','SETTLED','REVERSED')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),available_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(num_nonnulls(food_assignment_id,ride_assignment_id)=1));
CREATE INDEX earnings_driver_due ON earning_accruals(driver_id,state,available_at,id);
-- Sealing a posting prevents adding another balanced pair in a later transaction.
ALTER TABLE ledger_transactions ADD COLUMN posting_xid xid8 NOT NULL DEFAULT pg_current_xact_id();
CREATE FUNCTION draft067_ledger_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE t ledger_transactions;
BEGIN
 IF TG_TABLE_NAME='ledger_transactions' THEN
  NEW.posting_xid:=pg_current_xact_id();
  IF NEW.reverses_id=NEW.id THEN RAISE EXCEPTION 'SELF_REVERSAL' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT * INTO STRICT t FROM ledger_transactions WHERE id=NEW.transaction_id;
  IF t.posting_xid<>pg_current_xact_id() THEN RAISE EXCEPTION 'LEDGER_POSTING_SEALED' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER draft067_ledger_header BEFORE INSERT ON ledger_transactions FOR EACH ROW EXECUTE FUNCTION draft067_ledger_insert();
CREATE TRIGGER draft067_ledger_line BEFORE INSERT ON ledger_entries FOR EACH ROW EXECUTE FUNCTION draft067_ledger_insert();
CREATE FUNCTION draft067_ledger_reversal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE t ledger_transactions; original ledger_transactions;
BEGIN
 SELECT * INTO STRICT t FROM ledger_transactions WHERE id=NEW.id;
 IF t.reverses_id IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO STRICT original FROM ledger_transactions WHERE id=t.reverses_id;
 IF (t.currency,t.decimals) IS DISTINCT FROM (original.currency,original.decimals)
 OR EXISTS(
  SELECT account_id FROM (
   SELECT account_id,debit_minor AS d,credit_minor AS c FROM ledger_entries WHERE transaction_id=t.id
   UNION ALL SELECT account_id,-credit_minor,-debit_minor FROM ledger_entries WHERE transaction_id=original.id
  ) x GROUP BY account_id HAVING sum(d)<>0 OR sum(c)<>0
 ) THEN RAISE EXCEPTION 'INVALID_LEDGER_REVERSAL' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER draft067_ledger_reverse AFTER INSERT ON ledger_transactions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION draft067_ledger_reversal();

-- Frozen facts absent in 062. Finalization occurs only when driver identity exists.
CREATE TABLE order_allocation_finalizations(
 merchant_id uuid NOT NULL,order_id uuid NOT NULL,quote_id uuid NOT NULL,
 currency text NOT NULL CHECK(currency IN('USD','USDG')),decimals smallint NOT NULL CHECK(decimals IN(2,4,6)),
 total_minor bigint NOT NULL,posting_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 finalized_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(merchant_id,order_id),
 FOREIGN KEY(merchant_id,order_id) REFERENCES order_authority(merchant_id,order_id),
 FOREIGN KEY(merchant_id,quote_id) REFERENCES order_quotes(merchant_id,id)
);
CREATE TABLE earning_accrual_facts(
 accrual_id uuid PRIMARY KEY REFERENCES earning_accruals,amount_minor bigint NOT NULL,
 currency text NOT NULL CHECK(currency IN('USD','USDG')),decimals smallint NOT NULL CHECK(decimals IN(2,4,6)),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE ledger_entries ADD CHECK(debit_minor>=0 AND credit_minor>=0);
ALTER TABLE order_allocations ADD CHECK(amount_minor>=0);
ALTER TABLE order_allocation_finalizations ADD CHECK(total_minor>=0);
ALTER TABLE earning_accrual_facts ADD CHECK(amount_minor>=0);
CREATE TRIGGER earning_fact_immutable BEFORE UPDATE OR DELETE ON earning_accrual_facts FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE TRIGGER allocation_finalization_immutable BEFORE UPDATE OR DELETE ON order_allocation_finalizations FOR EACH ROW EXECUTE FUNCTION immutable_authority_row();
CREATE OR REPLACE FUNCTION draft067_ledger_reversal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,bitpos,pg_temp AS $$
DECLARE target uuid;t ledger_transactions;original ledger_transactions;
BEGIN
 IF TG_TABLE_NAME='ledger_entries' THEN target:=NEW.transaction_id;ELSE target:=NEW.id;END IF;
 FOR t IN SELECT * FROM ledger_transactions WHERE reverses_id IS NOT NULL AND (id=target OR reverses_id=target) LOOP
  SELECT * INTO STRICT original FROM ledger_transactions WHERE id=t.reverses_id;
  IF (t.currency,t.decimals) IS DISTINCT FROM (original.currency,original.decimals) OR EXISTS(
   SELECT account_id FROM (
    SELECT account_id,debit_minor AS d,credit_minor AS c FROM ledger_entries WHERE transaction_id=t.id
    UNION ALL SELECT account_id,-credit_minor,-debit_minor FROM ledger_entries WHERE transaction_id=original.id
   ) x GROUP BY account_id HAVING sum(d)<>0 OR sum(c)<>0
  ) THEN RAISE EXCEPTION 'INVALID_LEDGER_REVERSAL' USING ERRCODE='23514';END IF;
 END LOOP;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER ledger_entry_reversal AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION draft067_ledger_reversal();
DO $$ DECLARE name text;BEGIN
